+    // Fast path for already sorted or reverse sorted
+    bool sorted = true;
+    bool rev_sorted = true;
+    for (size_t i = 1; i < n; ++i) {
+        if (a[i] < a[i-1]) sorted = false;
+        if (a[i] > a[i-1]) rev_sorted = false;
+    }
+    if (sorted) return;
+    if (rev_sorted) {
+        std::reverse(a, a + n);
+        return;
+    }
+
+    std::vector<uint32_t> b(n);
+    uint32_t* src = a;
+    uint32_t* dst = b.data();
+
+    // 4-pass Radix Sort (8 bits per pass)
+    // This is more cache-friendly than 11-bit passes.
+    for (int pass = 0; pass < 4; ++pass) {
+        const int shift = pass * 8;
+        size_t count[256] = {0};
+        for (size_t i = 0; i < n; ++i) {
+            count[(src[i] >> shift) & 0xFF]++;
+        }
+        size_t offset[256];
+        offset[0] = 0;
+        for (int i = 1; i < 256; ++i) {
+            offset[i] = offset[i - 1] + count[i - 1];
+        }
+        for (size_t i = 0; i < n; ++i) {
+            dst[offset[(src[i] >> shift) & 0xFF]++] = src[i];
+        }
+        std::swap(src, dst);
+    }
+
+    // If the final result is in the scratch buffer, copy it back.
